package com.rgv.tradingbot.dto;

import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.Map;

/**
 * Represents a buy/sell/hold signal generated by the StrategyEngine
 * based on IndicatorService output, to be consumed by OrderExecutionService
 * and pushed to clients via TradeSignalWebSocketHandler.
 */
@Data
@Builder
@NoArgsConstructor
@AllArgsConstructor
public class TradeSignalDTO {

    private String symbol;

    // e.g. "BUY", "SELL", "HOLD"
    private String action;

    // Strategy that generated this signal (e.g. "SMA_CROSSOVER", "RSI")
    private String strategyName;

    private BigDecimal price;

    private BigDecimal quantity;

    // 0.0 - 1.0, how strong/confident the signal is
    private Double confidence;

    // Optional human-readable reason ("RSI < 30, oversold")
    private String reason;

    private LocalDateTime generatedAt;

    private Map<String, Double> indicators;
}